import type { Transition } from "motion/react";

export const easeOut = [0.23, 1, 0.32, 1] as const;

export const easeInOut = [0.77, 0, 0.175, 1] as const;

export const easeOutClass = "ease-[cubic-bezier(0.23,1,0.32,1)]";

export const duration = {
  fast: 0.14,
  base: 0.2,
  slow: 0.28,
} as const;

export const springSnappy = {
  type: "spring",
  duration: 0.24,
  bounce: 0,
} as const satisfies Transition;

export const springLayout = {
  type: "spring",
  duration: 0.3,
  bounce: 0,
} as const satisfies Transition;

export function transitionFor(
  reduceMotion: boolean | null,
  transition: Transition,
): Transition {
  return reduceMotion ? { duration: 0 } : transition;
}

export function edgeOffset(placement: string | null, distance: number) {
  switch (placement) {
    case "top":
      return { x: 0, y: distance };
    case "left":
      return { x: distance, y: 0 };
    case "right":
      return { x: -distance, y: 0 };
    default:
      return { x: 0, y: -distance };
  }
}

import { type CnOptions, cn as mergeClasses } from "tailwind-variants";

export function cn(...classes: CnOptions): string {
  return mergeClasses(...classes) ?? "";
}

export const fieldLabelStyles =
  "text-sm font-medium text-foreground [overflow-wrap:anywhere]";
export const fieldDescriptionStyles =
  "text-xs leading-5 text-muted-foreground [overflow-wrap:anywhere]";
export const fieldErrorStyles =
  "text-xs leading-5 text-destructive [overflow-wrap:anywhere]";

export const fieldInputStyles =
  "min-h-12 w-full cursor-text rounded-lg border border-input bg-card text-base text-foreground shadow-[var(--shadow-card)] outline-none transition-[color,background-color,border-color,box-shadow] duration-150 ease-[cubic-bezier(0.23,1,0.32,1)] placeholder:text-muted-foreground/80 hover:border-primary/45 focus:border-ring focus:ring-3 focus:ring-ring/50 invalid:border-destructive invalid:ring-3 invalid:ring-destructive/20 invalid:hover:border-destructive invalid:focus:border-destructive invalid:focus:ring-destructive/30 [&[readonly]]:bg-muted/40 [&[readonly]]:hover:border-input disabled:cursor-not-allowed disabled:bg-muted disabled:opacity-60 disabled:hover:border-input sm:text-sm";

export const segmentedFieldStyles =
  "flex min-h-12 min-w-0 items-center rounded-lg border border-input bg-card shadow-[var(--shadow-card)] transition-[color,background-color,border-color,box-shadow] duration-150 ease-[cubic-bezier(0.23,1,0.32,1)] hover:border-primary/45 focus-within:border-ring focus-within:hover:border-ring focus-within:ring-3 focus-within:ring-ring/50 group-invalid:border-destructive group-invalid:ring-3 group-invalid:ring-destructive/20 group-invalid:hover:border-destructive group-invalid:focus-within:border-destructive group-invalid:focus-within:hover:border-destructive group-invalid:focus-within:ring-destructive/30 group-data-[readonly]:bg-muted/40 group-data-[readonly]:hover:border-input group-disabled:bg-muted group-disabled:opacity-60 group-disabled:hover:border-input";

export const fieldTriggerStyles =
  "grid size-11 shrink-0 cursor-pointer place-items-center rounded-md text-muted-foreground outline-none transition-[color,background-color] duration-150 ease-[cubic-bezier(0.23,1,0.32,1)] hover:bg-muted hover:text-foreground pressed:bg-muted pressed:text-foreground focus-visible:-outline-offset-2 focus-visible:outline-2 focus-visible:outline-solid focus-visible:outline-ring disabled:cursor-default disabled:opacity-50";

"use client";

import { motion, useReducedMotion } from "motion/react";
import { createContext, type ReactNode, useContext } from "react";
import {
  SwitchButton as AriaSwitchButton,
  type SwitchButtonProps as AriaSwitchButtonProps,
  SwitchField as AriaSwitchField,
  type SwitchFieldProps as AriaSwitchFieldProps,
  composeRenderProps,
  FieldError,
  Text,
  useLocale,
  type ValidationResult,
} from "react-aria-components";
import { springSnappy, transitionFor } from "./motion";
import { cn } from "./utils";
import { fieldDescriptionStyles, fieldErrorStyles } from "./field-styles";

const SwitchStateContext = createContext({
  isSelected: false,
  isPressed: false,
  isDisabled: false,
});

export interface SwitchProps extends Omit<AriaSwitchFieldProps, "children"> {
  ref?: React.Ref<HTMLDivElement>;
  /** The label. Omit it and pass aria-label when the switch has no visible label. */
  children?: ReactNode;
  description?: ReactNode;
  errorMessage?: string | ((validation: ValidationResult) => string);
  checked?: boolean;
  defaultChecked?: boolean;
  onCheckedChange?: (checked: boolean) => void;
}

export function Switch({
  children,
  description,
  errorMessage,
  checked,
  defaultChecked,
  onCheckedChange,
  ...props
}: SwitchProps) {
  return (
    <SwitchField
      {...props}
      isSelected={checked ?? props.isSelected}
      defaultSelected={defaultChecked ?? props.defaultSelected}
      onChange={(isSelected) => {
        props.onChange?.(isSelected);
        onCheckedChange?.(isSelected);
      }}
    >
      <SwitchButton>
        {children != null && <SwitchLabel>{children}</SwitchLabel>}
        <SwitchControl>
          <SwitchThumb />
        </SwitchControl>
      </SwitchButton>
      {description != null && (
        <SwitchDescription>{description}</SwitchDescription>
      )}
      <SwitchError>{errorMessage}</SwitchError>
    </SwitchField>
  );
}

export function SwitchField({
  className,
  ...props
}: AriaSwitchFieldProps & React.RefAttributes<HTMLDivElement>) {
  return (
    <AriaSwitchField
      {...props}
      data-slot="switch"
      className={composeRenderProps(className, (className) =>
        cn(
          "relative inline-grid min-h-11 min-w-0 max-w-full grid-cols-[minmax(0,1fr)_auto] content-center items-center py-1 text-sm text-foreground disabled:opacity-50",
          className,
        ),
      )}
    />
  );
}

export function SwitchButton({
  className,
  children,
  ...props
}: AriaSwitchButtonProps & React.RefAttributes<HTMLLabelElement>) {
  return (
    <AriaSwitchButton
      {...props}
      data-slot="switch-button"
      className={composeRenderProps(className, (className) =>
        cn(
          // Spans the label and description rows so the control centers on
          // both. The ::after layer makes the whole field the hit area.
          "group/switch col-span-full row-[1/span_2] grid cursor-pointer grid-cols-subgrid grid-rows-subgrid items-center after:absolute after:inset-0 disabled:cursor-default read-only:cursor-default",
          className,
        ),
      )}
    >
      {composeRenderProps(children, (children, state) => (
        <SwitchStateContext.Provider value={state}>
          {children}
        </SwitchStateContext.Provider>
      ))}
    </AriaSwitchButton>
  );
}

export function SwitchLabel({
  className,
  ...props
}: React.HTMLAttributes<HTMLSpanElement>) {
  return (
    <span
      {...props}
      data-slot="switch-label"
      className={cn(
        "me-4 min-w-0 font-medium [overflow-wrap:anywhere]",
        className,
      )}
    />
  );
}

export function SwitchDescription({
  className,
  ...props
}: React.ComponentProps<typeof Text>) {
  return (
    <Text
      {...props}
      slot="description"
      data-slot="switch-description"
      className={cn(
        fieldDescriptionStyles,
        "col-start-1 row-start-2 me-4 mt-1",
        className,
      )}
    />
  );
}

export function SwitchError({
  className,
  ...props
}: React.ComponentProps<typeof FieldError>) {
  return (
    <FieldError
      {...props}
      data-slot="switch-error"
      // relative keeps the message above the hit area layer.
      className={cn(
        fieldErrorStyles,
        "relative col-span-full row-start-3 mt-1",
        className,
      )}
    />
  );
}

export function SwitchControl({
  className,
  ...props
}: React.HTMLAttributes<HTMLSpanElement>) {
  return (
    <span
      {...props}
      aria-hidden="true"
      data-slot="switch-control"
      className={cn(
        "row-span-2 flex h-6 w-10 shrink-0 items-center rounded-full bg-muted-foreground/75 p-0.5 shadow-[var(--shadow-inset)] transition-colors duration-200 ease-[cubic-bezier(0.23,1,0.32,1)] group-hover/switch:bg-muted-foreground group-selected/switch:bg-primary group-selected/switch:group-hover/switch:bg-primary/90 group-invalid/switch:ring-2 group-invalid/switch:ring-destructive group-focus-visible/switch:outline-2 group-focus-visible/switch:outline-solid group-focus-visible/switch:outline-offset-2 group-focus-visible/switch:outline-ring forced-colors:border forced-colors:border-[ButtonText] forced-colors:p-px forced-colors:group-selected/switch:border-[Highlight] forced-colors:group-disabled/switch:border-[GrayText]",
        className,
      )}
    />
  );
}

export function SwitchThumb({
  className,
  ...props
}: React.HTMLAttributes<HTMLSpanElement>) {
  const { isSelected, isPressed, isDisabled } = useContext(SwitchStateContext);
  const { direction } = useLocale();
  const reduceMotion = useReducedMotion();
  const width = !isDisabled && isPressed ? 24 : 20;
  const travel = 36 - width;
  return (
    <span
      {...props}
      aria-hidden="true"
      data-slot="switch-thumb"
      className={cn("contents", className)}
    >
      <motion.span
        initial={false}
        animate={{
          x: isSelected ? (direction === "rtl" ? -travel : travel) : 0,
          width,
        }}
        transition={transitionFor(reduceMotion, springSnappy)}
        className="size-5 shrink-0 rounded-full bg-card shadow-[var(--shadow-card)] transition-colors duration-200 ease-[cubic-bezier(0.23,1,0.32,1)] group-selected/switch:bg-primary-foreground forced-colors:bg-[ButtonText] forced-colors:group-selected/switch:bg-[Highlight] forced-colors:group-disabled/switch:bg-[GrayText]"
      />
    </span>
  );
}
